Here is the commit message:
afs: Fix the nlink handling of dir-over-dir rename

Fix rename of one directory over another such that the nlink on the deleted
directory is cleared to 0 rather than being decremented to 1.

This was causing the generic/035 xfstest to fail.

Fixes: e49c7b2f6de7 ("afs: Build an abstraction around an "operation" concept")
Signed-off-by: David Howells <dhowells@redhat.com>
Reviewed-by: Marc Dionne <marc.dionne@auristor.com>
cc: linux-afs@lists.infradead.org
Link: https://lore.kernel.org/r/162194384460.3999479.7605572278074191079.stgit@warthog.procyon.org.uk/ # v1
Signed-off-by: Linus Torvalds <torvalds@linux-foundation.org>

Here is the root cause:
The bug was caused by the incorrect handling of the link count (`i_nlink`) for directories during a rename operation. Instead of clearing the link count to 0 when a directory is renamed over another, it was being decremented, which led to an incorrect state in the file system and caused the `generic/035` xfstest to fail.

Here is the patch:

 static void afs_rename_edit_dir(struct afs_operation *op)
 {
 	struct afs_vnode_param *orig_dvp = &op->file[0];
 	struct afs_vnode_param *new_dvp = &op->file[1];
 	struct afs_vnode *orig_dvnode = orig_dvp->vnode;
 	struct afs_vnode *new_dvnode = new_dvp->vnode;
 	struct afs_vnode *vnode = AFS_FS_I(d_inode(op->dentry));
 	struct dentry *old_dentry = op->dentry;
 	struct dentry *new_dentry = op->dentry_2;
 	struct inode *new_inode;

 	_enter("op=%08x", op->debug_id);

 	if (op->rename.rehash) {
 		d_rehash(op->rename.rehash);
 		op->rename.rehash = NULL;
 	}

 	down_write(&orig_dvnode->validate_lock);
 	if (test_bit(AFS_VNODE_DIR_VALID, &orig_dvnode->flags) &&
 	    orig_dvnode->status.data_version == orig_dvp->dv_before + orig_dvp->dv_delta)
 		afs_edit_dir_remove(orig_dvnode, &old_dentry->d_name,
 				    afs_edit_dir_for_rename_0);

 	if (new_dvnode != orig_dvnode) {
 		up_write(&orig_dvnode->validate_lock);
 		down_write(&new_dvnode->validate_lock);
 	}

 	if (test_bit(AFS_VNODE_DIR_VALID, &new_dvnode->flags) &&
 	    new_dvnode->status.data_version == new_dvp->dv_before + new_dvp->dv_delta) {
 		if (!op->rename.new_negative)
 			afs_edit_dir_remove(new_dvnode, &new_dentry->d_name,
 					    afs_edit_dir_for_rename_1);

 		afs_edit_dir_add(new_dvnode, &new_dentry->d_name,
 				 &vnode->fid, afs_edit_dir_for_rename_2);
 	}

 	new_inode = d_inode(new_dentry);
 	if (new_inode) {
 		spin_lock(&new_inode->i_lock);
-		if (new_inode->i_nlink > 0)
+		if (S_ISDIR(new_inode->i_mode))
+			clear_nlink(new_inode);
+		else if (new_inode->i_nlink > 0)
 			drop_nlink(new_inode);
 		spin_unlock(&new_inode->i_lock);
 	}

 	/* Now we can update d_fsdata on the dentries to reflect their
 	 * new parent's data_version.
 	 *
 	 * Note that if we ever implement RENAME_EXCHANGE, we'll have
 	 * to update both dentries with opposing dir versions.
 	 */
 	afs_update_dentry_version(op, new_dvp, op->dentry);
 	afs_update_dentry_version(op, new_dvp, op->dentry_2);

 	d_move(old_dentry, new_dentry);

 	up_write(&new_dvnode->validate_lock);
 }



